@startuml

class City {
  + Name : string
}

class H2SLocation {
  + Name : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class ScheduledPickup {
  + Description : string
  + RequestedDate : date
  + RequestedTime : time
}

class Vehicle {
  + StorageSpace : float
}

class VolunteerDriver {
  + AvailableDays : string[]
}

class PickupRoute {
  + Date : date
}

class Item {
  + Dimensions : string
  + Weight : float
  + IsNonPerishableFood : boolean
}

class DistributionCenter {
}

class FoodBank {
}

class H2SEmployee {
}

class Article {
  + RFIDTag : string
  + Description : string
  + Category : string
}

class Client {
  + HomeAddress : string
  + NeededCategories : string[]
}

class Delivery {
  + Date : date
}

City "1" -- "*" H2SLocation
H2SLocation "1" -- "0..1" DistributionCenter
H2SLocation "1" -- "0..1" FoodBank

Resident "1" -- "*" ScheduledPickup
ScheduledPickup "*" -- "1" Item

Vehicle "1" -- "*" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute
PickupRoute "1" -- "*" ScheduledPickup

Item "*" -- "1" DistributionCenter : droppedOff
Item "*" -- "1" FoodBank : droppedOff

DistributionCenter "1" -- "*" Article
H2SEmployee "1" -- "*" Article : examinesAndTags
H2SEmployee "1" -- "*" Delivery : arranges

Client "1" -- "*" Delivery
Article "*" -- "1" Delivery

@enduml

